import{_ as t,c as e,o,a4 as n}from"./chunks/framework.BYxathSa.js";const m=JSON.parse('{"title":"Q7：CSS 中水平垂直居中的各种方法","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q7.md","filePath":"frontend/q7.md","lastUpdated":null}'),r={name:"frontend/q7.md"},s=n('<h1 id="q7-css-中水平垂直居中的各种方法" tabindex="-1">Q7：CSS 中水平垂直居中的各种方法 <a class="header-anchor" href="#q7-css-中水平垂直居中的各种方法" aria-label="Permalink to &quot;Q7：CSS 中水平垂直居中的各种方法&quot;">​</a></h1><p><strong>水平居中</strong></p><ul><li><strong>行内元素/文本</strong>：父元素 <code>text-align: center</code>。</li><li><strong>块级元素</strong>：自身 <code>margin: 0 auto</code>（需设定宽度）。</li><li><strong>Flexbox</strong>：父元素 <code>display: flex; justify-content: center</code>。</li><li><strong>绝对定位</strong>：<code>position: absolute; left: 50%; transform: translateX(-50%)</code> 或配合 <code>margin-left</code> 负自身一半宽度。</li></ul><p><strong>垂直居中</strong></p><ul><li><strong>单行文本</strong>：<code>line-height</code> 等于容器高度。</li><li><strong>Flexbox</strong>：父元素 <code>display: flex; align-items: center</code>。</li><li><strong>Grid</strong>：父元素 <code>display: grid; align-items: center</code>（或用简写 <code>place-items: center</code>）。</li><li><strong>绝对定位 + transform</strong>：<code>top: 50%; transform: translateY(-50%)</code>。</li><li><strong>表格单元格</strong>：父元素 <code>display: table-cell; vertical-align: middle</code>。</li></ul><p><strong>水平垂直同时居中</strong></p><ul><li><strong>Flexbox</strong>：父元素 <code>display: flex; justify-content: center; align-items: center</code>。</li><li><strong>Grid</strong>：<code>display: grid; place-items: center</code>。</li><li><strong>绝对定位 + transform</strong>：<code>position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%)</code>。</li></ul>',7),l=[s];function i(a,c,d,g,p,_){return o(),e("div",null,l)}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
